// ---------------------------------------------------------------- sequence
// Insert the `sep` trial(s) after every n trials of `main` (not after the last one).
// Defined here rather than relying on the Farm's sepWithN, which stock Ibex lacks.
function BreakEvery(sep, main, n) {
    this.args = [sep, main];
    this.run = function (arrays) {
        const sep = arrays[0], main = arrays[1], out = [];
        main.forEach((m, i) => {
            out.push(m);
            if ((i + 1) % n === 0 && i < main.length - 1) sep.forEach(s => out.push(s));
        });
        return out;
    };
}
function breakEvery(sep, main, n) { return new BreakEvery(sep, main, n); }

// Lists: the Farm hands the page its counter value when the page loads (list = counter mod n lists), and
// SetCounter below moves the counter on once the session starts. Sessions that load within a few seconds
// of each other therefore get the same list, and each such collision also skips the next list (both
// sessions increment). Abandoned sessions use up a list too. Balance comes from allocation, not from
// the counter: see "Recruiting and list balance" in ibex/README.md (withsquare=N forces list N).
SetCounter("counter", "inc", 1);   // advance the Latin-square counter as soon as a participant starts

// Calibration block (optional, CFG.calibrationFile): feedback after each sentence, then a summary.
const CALIBRATION = CFG.calibrationFile
    ? ["calib-intro", randomize("calib"), "calib-summary"]
    : [];

Sequence(
    "counter",
    "welcome", "demographics",
    "instructions",
    "practice",
    ...CALIBRATION,
    "begin",
    // Plain random order of all critical + filler trials. KAD's rshuffle(startsWith("Exp")) did the
    // same: rshuffle with a single predicate is just randomize().
    breakEvery("break", randomize(startsWith("exp-")), CFG.breakEvery),
    "debrief",
    "send",
    "end"
);

